/**
 * SCRIPT_BANK_05 — bank5 剧情脚本数据 ($A000-$BFFF 窗口)
 *
 * 每个脚本一条 JSON: instructions 数组 (指令流语义) + text 字段 (可读日文)。
 * 由 asm/bank05/_full.s 逐字节解析 (脚本入口指针表 → 指令流)。
 *
 * 指令分类:
 *   opcode < 0xD8  文本字符 (单/双 tile)
 *   0xD8-0xDF      等待帧
 *   0xE1-0xE7      行编辑
 *   0xE8-0xFF      长指令
 *
 * text 字段为脚本文本区解码的可读日文 (逐字符映射 char-map-table)。
 * 这是脚本翻译层最终产物, 禁止对 PRG_BANK 原始字节随机访问。
 */
